using System.Text;
using System.Text.Json;
using EvalAI.Database.Persistence;
using EvalAI.Domain.DTOs;
using EvalAI.Domain.Entities;
using EvalAI.Domain.Models;
using EvalAI.Services.Evaluations;
using EvalAI.Services.Documents;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace EvalAI.Tests;

public sealed class IntegrationTests
{
    static JsonElement J(string s) => JsonDocument.Parse(s).RootElement.Clone();
    static CreateDatasetRequest Dataset(string version = "v1", int answer = 3) => new("Test", version, [new("Sum", J("{\"operation\":\"sum\",\"values\":[1,2]}"), J($"{{\"answer\":{answer}}}"))]);
    [Fact] public async Task SeedRunsEndToEndAndMissingCostIsNull() { await using var rig = await new TestRig().InitializeAsync(); await rig.Datasets.SeedAsync(default); await using var db = rig.Factory.CreateDbContext(); var dataset = await db.EvalDatasets.SingleAsync(); var run = await rig.Evaluations.CreateAsync(new(dataset.Id, [VariantCatalog.A, VariantCatalog.B]), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(run.Id); var report = JsonSerializer.SerializeToElement(await rig.Evaluations.ReportAsync(run.Id, default), JsonDefaults.Options); Assert.Equal("Completed", report.GetProperty("state").GetString()); var summaries = report.GetProperty("summaries").EnumerateArray().ToArray(); Assert.Equal(3, summaries[0].GetProperty("passed").GetInt32()); Assert.Equal(2, summaries[1].GetProperty("passed").GetInt32()); Assert.All(report.GetProperty("results").EnumerateArray(), r => Assert.Equal(JsonValueKind.Null, r.GetProperty("candidateCost").GetProperty("amount").ValueKind)); Assert.Equal(504, report.GetProperty("usedTokens").GetInt32()); Assert.Equal(6, rig.Ai.CandidateCalls); Assert.Equal(6, rig.Ai.JudgeCalls); }
    [Fact] public async Task GoldenVersionIsImmutableAndBaselineMismatchRejected() { await using var rig = await new TestRig().InitializeAsync(); var d = await rig.Datasets.CreateAsync(Dataset(), default); await Assert.ThrowsAsync<AppException>(() => rig.Datasets.CreateAsync(Dataset(), default)); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(run.Id); var other = await rig.Datasets.CreateAsync(Dataset("v2"), default); var e = await Assert.ThrowsAsync<AppException>(() => rig.Evaluations.CreateAsync(new(other.Id, [VariantCatalog.A], run.Id), default)); Assert.Equal("incompatible_baseline", e.Code); var same = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A], run.Id), default); await rig.WaitRunAsync(same.Id); var report = JsonSerializer.SerializeToElement(await rig.Evaluations.ReportAsync(same.Id, default), JsonDefaults.Options); Assert.True(report.GetProperty("baselineCompatible").GetBoolean()); Assert.False(report.GetProperty("summaries")[0].GetProperty("regression").GetBoolean()); }
    [Fact] public async Task CandidateCheckpointSurvivesJudgeRetry() { await using var rig = await new TestRig().InitializeAsync(); rig.Ai.FailJudgeCount = 1; var d = await rig.Datasets.CreateAsync(Dataset(), default); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(run.Id); Assert.Equal(1, rig.Ai.CandidateCalls); Assert.Equal(2, rig.Ai.JudgeCalls); await using var db = rig.Factory.CreateDbContext(); Assert.Equal("Completed", (await db.EvalRuns.SingleAsync()).State); Assert.Single(await db.EvalCaseResults.ToArrayAsync()); }
    [Fact] public async Task ManualRetryOnlyCallsFailedStage() { await using var rig = await new TestRig().InitializeAsync(); rig.Ai.FailJudgeCount = 1; rig.Ai.JudgeStatus = 502; var d = await rig.Datasets.CreateAsync(Dataset(), default); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(run.Id); int revision; await using (var db = rig.Factory.CreateDbContext()) { var saved = await db.EvalRuns.SingleAsync(); Assert.Equal("Failed", saved.State); revision = saved.Revision; } await rig.Evaluations.RetryAsync(run.Id, revision, default); await rig.WaitRunAsync(run.Id); Assert.Equal(1, rig.Ai.CandidateCalls); Assert.Equal(2, rig.Ai.JudgeCalls); }
    [Fact] public async Task LeaseClaimIsExclusiveAndExpiredLeaseCannotCheckpoint() { await using var rig = await new TestRig().InitializeAsync(); var job = new IngestionJob { Kind = "Test" }; await using (var db = rig.Factory.CreateDbContext()) { db.Add(job); await db.SaveChangesAsync(); } var claims = await Task.WhenAll(Enumerable.Range(0, 8).Select(_ => rig.Jobs.ClaimAsync(default))); Assert.Single(claims, j => j != null); var first = claims.Single(j => j != null)!; await using (var db = rig.Factory.CreateDbContext()) { await db.IngestionJobs.Where(j => j.Id == job.Id).ExecuteUpdateAsync(s => s.SetProperty(j => j.LeaseUntilUtc, DateTimeOffset.UtcNow.AddSeconds(-1))); } var second = await rig.Jobs.ClaimAsync(default); Assert.NotNull(second); Assert.NotEqual(first.LeaseToken, second.LeaseToken); await using (var db = rig.Factory.CreateDbContext()) await Assert.ThrowsAsync<AppException>(() => EvalAI.Services.Jobs.DurableWorker.GuardAsync(db, first, default)); }
    [Fact] public async Task ResultUniqueConstraintAndRevisionConcurrencyUseRealPostgres() { await using var rig = await new TestRig().InitializeAsync(); var d = await rig.Datasets.CreateAsync(Dataset(), default); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await using (var db = rig.Factory.CreateDbContext()) { var row = await db.EvalCaseResults.SingleAsync(); db.Add(new EvalCaseResult { RunId = row.RunId, VariantId = row.VariantId, CaseId = row.CaseId }); await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync()); } await using var one = rig.Factory.CreateDbContext(); await using var two = rig.Factory.CreateDbContext(); var a = await one.EvalRuns.SingleAsync(); var b = await two.EvalRuns.SingleAsync(); a.Revision++; await one.SaveChangesAsync(); b.Revision++; await Assert.ThrowsAsync<DbUpdateConcurrencyException>(() => two.SaveChangesAsync()); }
    [Fact] public async Task S3UploadDeduplicatesExtractsAndDeletionStalesRuns() { await using var rig = await new TestRig().InitializeAsync(); const string content = "Artificial evidence: the sum of 1 and 2 is 3."; using var s = new MemoryStream(Encoding.UTF8.GetBytes(content)); var uploaded = await rig.Documents.UploadAsync("seed.txt", s, default); s.Position = 0; var duplicate = await rig.Documents.UploadAsync("seed.txt", s, default); Assert.True(duplicate.Existing); Assert.Equal(uploaded.DocumentId, duplicate.DocumentId); await rig.StartWorkerAsync(); Document? doc = null; for (int i = 0; i < 100; i++) { doc = await rig.Documents.GetAsync(uploaded.DocumentId, default); if (doc.Status == "Ready") break; await Task.Delay(100); } Assert.Equal("Ready", doc!.Status); await using var db = rig.Factory.CreateDbContext(); var chunk = await db.DocumentChunks.SingleAsync(); Assert.Equal(content, chunk.Text); await using (var original = await rig.Storage.OpenReadAsync(doc.ObjectKey, default)) { using var reader = new StreamReader(original); Assert.Equal(content, await reader.ReadToEndAsync()); } var d = await rig.Datasets.CreateAsync(new("Evidence", "v1", [new("Sum", Dataset().Cases[0].Input, Dataset().Cases[0].Expected, [chunk.Id])]), default); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.WaitRunAsync(run.Id); await rig.Documents.DeleteAsync(doc.Id, default); db.ChangeTracker.Clear(); Assert.True((await db.EvalRuns.SingleAsync()).Stale); await Assert.ThrowsAsync<AppException>(() => rig.Documents.GetAsync(doc.Id, default)); await Assert.ThrowsAsync<AppException>(() => rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default)); }
    [Fact] public async Task RatesAreSnapshottedAndNeverAppliedRetroactively() { await using var rig = await new TestRig().InitializeAsync(); var d = await rig.Datasets.CreateAsync(Dataset(), default); var run = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.Evaluations.AddRateAsync(new("evalai-a", "rate-v1", "USD", 1, 2), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(run.Id); var next = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.WaitRunAsync(next.Id); var old = JsonSerializer.SerializeToElement(await rig.Evaluations.ReportAsync(run.Id, default), JsonDefaults.Options); var latest = JsonSerializer.SerializeToElement(await rig.Evaluations.ReportAsync(next.Id, default), JsonDefaults.Options); Assert.Equal(JsonValueKind.Null, old.GetProperty("results")[0].GetProperty("candidateCost").GetProperty("amount").ValueKind); Assert.Equal(0.000054m, decimal.Parse(latest.GetProperty("results")[0].GetProperty("candidateCost").GetProperty("amount").GetString()!, System.Globalization.CultureInfo.InvariantCulture)); }
    [Fact] public async Task CancellationAndBudgetStopWorkWithoutFabricatedScores() { await using var rig = await new TestRig().InitializeAsync(); await rig.Datasets.SeedAsync(default); await using var db = rig.Factory.CreateDbContext(); var d = await db.EvalDatasets.SingleAsync(); var canceled = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A]), default); await rig.Evaluations.CancelAsync(canceled.Id, canceled.Revision, default); var limited = await rig.Evaluations.CreateAsync(new(d.Id, [VariantCatalog.A, VariantCatalog.B], BudgetTokens: 256), default); await rig.StartWorkerAsync(); await rig.WaitRunAsync(limited.Id); db.ChangeTracker.Clear(); Assert.Equal("Canceled", (await db.EvalRuns.SingleAsync(r => r.Id == canceled.Id)).State); Assert.True((await db.EvalRuns.SingleAsync(r => r.Id == limited.Id)).UsedTokens <= 256); Assert.Contains(await db.EvalCaseResults.Where(r => r.RunId == limited.Id).ToArrayAsync(), r => r.ErrorCode != null); }
}
